#!/usr/bin/env python3
"""Profile the full serving decode path"""

import torch
import json
import time
from torch.profiler import profile, ProfilerActivity

# Import sglang
import sys
sys.path.insert(0, '/sgl-workspace/sglang/python')

def profile_serving_decode():
    from sglang.srt.server import launch_server
    from sglang.srt.managers.scheduler import Scheduler
    import requests

    # This is complex - let's just do a simpler approach
    # Run bench_serving with profiling enabled
    print("Please run with: python3 -m sglang.bench_serving --profile ...")
    print("For now, showing kernel breakdown from previous profile...")

    # Read the trace from our earlier profile
    try:
        with open("/tmp/decode_trace.json") as f:
            events = json.load(f)["traceEvents"]

        gpu_kernels = {}
        for e in events:
            if e.get("cat") == "kernel":
                name = e["name"]
                dur = e.get("dur", 0)
                gpu_kernels[name] = gpu_kernels.get(name, 0) + dur

        total = sum(gpu_kernels.values())
        print(f"\nKernel breakdown from decode attention profile:")
        print(f"{'Pct':>6} {'Time(ms)':>10} {'Kernel'}")
        print("-" * 80)

        for name, dur in sorted(gpu_kernels.items(), key=lambda x: -x[1])[:10]:
            pct = dur / total * 100 if total else 0
            # Categorize
            if "stage1" in name.lower() or "grouped" in name.lower():
                category = "ATTN_STAGE1"
            elif "stage2" in name.lower() or "reduce" in name.lower() or "softmax" in name.lower():
                category = "ATTN_REDUCE"
            else:
                category = "OTHER"
            print(f"{pct:5.1f}% {dur/1000:9.1f}ms  [{category}] {name[:60]}")

        # Sum by category
        categories = {}
        for name, dur in gpu_kernels.items():
            if "stage1" in name.lower() or "grouped" in name.lower():
                cat = "ATTN_STAGE1"
            elif "stage2" in name.lower() or "reduce" in name.lower() or "softmax" in name.lower():
                cat = "ATTN_REDUCE"
            else:
                cat = "OTHER"
            categories[cat] = categories.get(cat, 0) + dur

        print(f"\n{'Category':<20} {'Time(ms)':>10} {'Pct':>6}")
        print("-" * 40)
        for cat, dur in sorted(categories.items(), key=lambda x: -x[1]):
            pct = dur / total * 100 if total else 0
            print(f"{cat:<20} {dur/1000:9.1f} {pct:5.1f}%")

    except Exception as e:
        print(f"Error reading trace: {e}")

if __name__ == "__main__":
    profile_serving_decode()
